is_oa": true, "is_in_doaj": false, "is_core": false, "listed_in": [], "host_organization": "https://openalex.org/P4310312730", "host_organization_name": "Institute of Computer Science", "host_organization_lineage": ["https://openalex.org/P4310312730"], "host_organization_lineage_names": ["Institute of Computer Science"], "type": "journal"}, "license": "cc-by-nc", "license_id": "https://openalex.org/licenses/cc-by-nc", "version": "publishedVersion", "is_accepted": true, "is_published": true, "raw_source_name": "2089-8185", "raw_type": "info:eu-repo/semantics/article"}, "abstract": "The rapid growth of scientific publications and the increasing complexity of multidisciplinary research have made conventional scientific discovery slower, less scalable, and less effective in identifying hidden knowledge across research domains. Recent advances in Generative Artificial Intelligence (Generative AI), Large Language Models (LLMs), and knowledge graphs offer new opportunities to automate scientific discovery. This study aims to develop and evaluate an Autonomous Scientific Discovery System Based on Generative AI capable of integrating scientific knowledge, understanding literature, generating hypotheses, planning experiments, performing scientific reasoning, and producing structured research reports. The study adopts the Design Science Research (DSR) methodology to design and evaluate an intelligent prototype integrating knowledge graphs, literature understanding, Generative AI, Retrieval-Augmented Generation (RAG), scientific reasoning, hypothesis generation, experiment planning, evidence evaluation, and automated report generation. System performance is evaluated using expert assessment, scientific validation, and quantitative metrics, including Hypothesis Quality Score, Scientific Validity, Novelty, Precision, Recall, F1-score, BERTScore, Explainability Score, Time Reduction, and Discovery Success Rate. The results demonstrate that the proposed system successfully automates literature analysis, knowledge synthesis, hypothesis generation, and experiment planning, significantly improving research efficiency, hypothesis quality, interdisciplinary knowledge integration, and explainability compared with conventional research workflows. These findings demonstrate the feasibility of autonomous AI-supported scientific discovery while emphasizing the importance of rigorous validation, explainable reasoning, ethical governance, and human oversight for future deployment."}]", "excerpt_truncated": true, "source_sha256": "cc626e2986cab77c683db77164291116147129b1c3a6648120ed332fd69ed763", "verification_required": true, "topic_domain": "unassigned_problem", "evidence_role": "discovery", "host_tier": "discovery", "source_identity": null, "persistent_identifiers": ["doi:10.48550/arxiv.2609.31562", "openalex:W7214619401", "arxiv:2609.31562"], "source_candidates": ["https://doi.org/10.48550/arxiv.2609.31562", "https://arxiv.org/pdf/2609.31562", "https://arxiv.org/abs/2609.31562"], "source_candidate_identities": {}}
